using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.Networking;
using TMPro;

[System.Serializable]
public class TranscriptionResponse
{
    public string text;
}

public class AudioTranscriptionHandler : MonoBehaviour
{
    [SerializeField] private TMP_InputField responseText;
    [SerializeField] private string apiKey;
    [SerializeField] private string apiUrl = "https://api.openai.com/v1/audio/transcriptions";

    public void Transcribe(string filePath)
    {
        StartCoroutine(UploadAudio(filePath));
    }

    private IEnumerator UploadAudio(string filePath)
    {
        if (!File.Exists(filePath))
        {
            Debug.LogError("Audio file does not exist: " + filePath);
            yield break;
        }

        byte[] audioBytes = File.ReadAllBytes(filePath);
        string fileName = Path.GetFileName(filePath);
        string mimeType = fileName.EndsWith(".mp3") ? "audio/mpeg" : "audio/wav";

        List<IMultipartFormSection> formData = new List<IMultipartFormSection>();
        formData.Add(new MultipartFormFileSection("file", audioBytes, fileName, mimeType));
        formData.Add(new MultipartFormDataSection("model", "whisper-1"));

        using (UnityWebRequest request = UnityWebRequest.Post(apiUrl, formData))
        {
            request.SetRequestHeader("Authorization", "Bearer " + apiKey);
            request.timeout = 120;

            yield return request.SendWebRequest();

            if (request.result != UnityWebRequest.Result.Success)
            {
                Debug.LogError("Transcription request failed: " + request.error);
                Debug.LogError(request.downloadHandler.text);
                yield break;
            }

            TranscriptionResponse response =
                JsonUtility.FromJson<TranscriptionResponse>(request.downloadHandler.text);

            if (response != null && !string.IsNullOrEmpty(response.text))
            {
                responseText.text = response.text;
                Debug.Log("Transcription: " + response.text);
            }
            else
            {
                Debug.LogError("The response did not contain transcription text.");
            }
        }
    }
}

